use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;

const K_EVENT: u8 = b'E';
const K_COLUMN: u8 = b'X';
const K_ACTOR: u8 = b'P';
/// Item index: `uid(8) seq(8)` -> empty; "this item instance was involved at
/// seq". Like the column and actor indexes it holds no payload, so the whole
/// history of one item is a prefix scan of its own entries rather than a walk
/// of the journal.
const K_ITEM: u8 = b'I';
/// Key written by earlier versions: the last sequence number used. Read only,
/// to resume a journal that predates [`K_RESERVED`].
const K_HEAD: &[u8] = b"H";
/// Key holding the reservation bound: every sequence number below it may
/// have been handed out, none at or above it has. A restart resumes *at* the
/// bound, so no number is ever reused — not after a crash between an event
/// and any bookkeeping, and not when concurrent appends finish out of order.
const K_RESERVED: &[u8] = b"N";
/// How many sequence numbers one reservation write covers. The bound is
/// written once per block rather than once per event; the price is a gap of
/// up to this many unused numbers after a restart, which nothing depends on.
const SEQ_BLOCK: u64 = 4096;

fn event_key(seq: u64) -> [u8; 9] {
    let mut k = [0u8; 9];
    k[0] = K_EVENT;
    k[1..].copy_from_slice(&seq.to_be_bytes());
    k
}

fn column_prefix(cx: i32, cz: i32) -> [u8; 9] {
    let mut k = [0u8; 9];
    k[0] = K_COLUMN;
    // Biased to unsigned so that byte order matches numeric order for negative
    // coordinates too. Without the bias, column -1 would sort above column 1
    // and a prefix scan would still work (it is an exact-match prefix), but the
    // ordering guarantee is cheap and stops the next reader from wondering.
    k[1..5].copy_from_slice(&(cx as u32 ^ 0x8000_0000).to_be_bytes());
    k[5..9].copy_from_slice(&(cz as u32 ^ 0x8000_0000).to_be_bytes());
    k
}

fn column_key(cx: i32, cz: i32, seq: u64) -> [u8; 17] {
    let mut k = [0u8; 17];
    k[..9].copy_from_slice(&column_prefix(cx, cz));
    k[9..].copy_from_slice(&seq.to_be_bytes());
    k
}

fn actor_prefix(actor: ActorId) -> [u8; 17] {
    let mut k = [0u8; 17];
    k[0] = K_ACTOR;
    k[1..].copy_from_slice(&actor.0.to_be_bytes());
    k
}

fn actor_key(actor: ActorId, seq: u64) -> [u8; 25] {
    let mut k = [0u8; 25];
    k[..17].copy_from_slice(&actor_prefix(actor));
    k[17..].copy_from_slice(&seq.to_be_bytes());
    k
}

fn item_prefix(uid: ItemUid) -> [u8; 9] {
    let mut k = [0u8; 9];
    k[0] = K_ITEM;
    k[1..].copy_from_slice(&uid.0.to_be_bytes());
    k
}

fn item_key(uid: ItemUid, seq: u64) -> [u8; 17] {
    let mut k = [0u8; 17];
    k[..9].copy_from_slice(&item_prefix(uid));
    k[9..].copy_from_slice(&seq.to_be_bytes());
    k
}

/// Which events a rollback should undo.
///
/// The three restrictions are independent and combine with AND: an empty
/// filter selects the whole history, which is what "roll back everything"
/// means.
#[derive(Debug, Clone, Default)]
pub struct Filter {
    /// Only this player's actions. `None` selects every actor.
    pub actor: Option<ActorId>,
    /// Only within `radius` blocks of `(x, y, z)`, measured horizontally so
    /// that "clear this area" reaches from bedrock to sky as a player expects.
    pub area: Option<(i32, i32, i32, u32)>,
    /// Only events at or after this sequence number.
    pub since_seq: u64,
    /// Only events at or after this wall-clock time (Unix milliseconds).
    pub since_ms: u64,
}

impl Filter {
    /// Everything, from the beginning of the world.
    pub fn everything() -> Self {
        Self::default()
    }
    /// Restrict to one actor.
    pub fn by(mut self, actor: ActorId) -> Self {
        self.actor = Some(actor);
        self
    }
    /// Restrict to a horizontal radius around a point.
    pub fn near(mut self, x: i32, y: i32, z: i32, radius: u32) -> Self {
        self.area = Some((x, y, z, radius));
        self
    }
    /// Restrict to events no older than `ms`.
    pub fn since_time(mut self, ms: u64) -> Self {
        self.since_ms = ms;
        self
    }

    /// Whether `e` is selected.
    ///
    /// Public so a caller that has its own extra conditions (the command
    /// layer's `block:` / `action:` filters) ANDs them with the journal's
    /// exact selection instead of re-implementing — and drifting from — it.
    pub fn matches(&self, e: &Event) -> bool {
        if let Some(a) = self.actor {
            if e.actor != a {
                return false;
            }
        }
        if e.seq < self.since_seq || e.at_ms < self.since_ms {
            return false;
        }
        if let Some((cx, _cy, cz, r)) = self.area {
            // A bulk-edit revision spans many positions, so "is it in this
            // area?" means "does any of its changes land here?" — a revision
            // that reaches into the area is selected whole, and its rollback
            // restores every position it touched, not only the ones inside.
            if let EventBody::BlockGroup { changes } = &e.body {
                return changes.iter().any(|c| within(c.x, c.z, cx, cz, r));
            }
            let Some((x, _y, z)) = e.position() else {
                // Positionless events (an item moving between two inventory
                // slots) belong to no area, so an area-restricted rollback
                // leaves them alone rather than guessing.
                return false;
            };
            if !within(x, z, cx, cz, r) {
                return false;
            }
        }
        true
    }
}

/// Whether `(x, z)` lies within `r` blocks horizontally of `(cx, cz)`.
fn within(x: i32, z: i32, cx: i32, cz: i32, r: u32) -> bool {
    let (dx, dz) = ((x - cx) as i64, (z - cz) as i64);
    let r = r as i64;
    dx * dx + dz * dz <= r * r
}

/// One block restoration produced by a rollback plan.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Restore {
    pub x: i32,
    pub y: i32,
    pub z: i32,
    /// The state to put back.
    pub block: BlockStateId,
    /// The state the rollback is taking away — what the undone edit *placed*.
    ///
    /// This, not the world's current content, is what a recovery stash is owed:
    /// if someone has since built on top of the thing being undone, the
    /// current block belongs to them and handing it over would duplicate it.
    pub removed: BlockStateId,
    /// The sequence number of the event being undone, for the record.
    pub undoing: u64,
}

/// The append-only log over a KV backend.
pub struct Journal<B: KvBackend> {
    backend: B,
    next_seq: AtomicU64,
    /// The persisted reservation bound ([`K_RESERVED`]).
    reserved: Reservation,
    /// Optional mirror into an external database. See [`sink`].
    sink: Option<BatchingSink>,
}

fn read_u64(v: Option<Vec<u8>>) -> Option<u64> {
    v.filter(|v| v.len() == 8)
        .map(|v| u64::from_be_bytes(v.try_into().unwrap()))
}

/// Read a persisted reservation bound: `None` when absent, an error when
/// present but malformed. A malformed bound must never read as absent — for a
/// counter with nothing else to resume from, "absent" means "start at 1", which
/// would hand out every number again.
pub(crate) fn read_bound<B: KvBackend + ?Sized>(
    backend: &B,
    key: &[u8],
) -> Result<Option<u64>, StorageError> {
    match backend.get(key)? {
        None => Ok(None),
        Some(v) if v.len() == 8 => Ok(Some(u64::from_be_bytes(v.try_into().unwrap()))),
        Some(v) => Err(StorageError::Codec(format!(
            "reservation bound {} is {} bytes, not 8",
            String::from_utf8_lossy(key),
            v.len()
        ))),
    }
}

/// A persisted "no number at or above this has been handed out" bound for a
/// monotonic counter, raised a whole block at a time.
///
/// The common case — the number is below the bound — is one atomic load and
/// no lock. Raising takes the lock, re-checks, and makes the new bound durable
/// *before* publishing it, so no caller can return a number the store does
/// not already cover; two raisers can never write the bound backwards.
pub(crate) struct Reservation {
    key: &'static [u8],
    block: u64,
    bound: AtomicU64,
    raise: Mutex<()>,
}

impl Reservation {
    /// A reservation whose persisted bound is `start` (nothing reserved above it).
    pub(crate) fn new(key: &'static [u8], block: u64, start: u64) -> Self {
        Self {
            key,
            block,
            bound: AtomicU64::new(start),
            raise: Mutex::new(()),
        }
    }

    /// Make sure `v` lies below the persisted bound.
    pub(crate) fn ensure<B: KvBackend + ?Sized>(
        &self,
        backend: &B,
        v: u64,
    ) -> Result<(), StorageError> {
        if v < self.bound.load(Ordering::Acquire) {
            return Ok(());
        }
        let _raising = self.raise.lock().unwrap();
        if v < self.bound.load(Ordering::Acquire) {
            return Ok(());
        }
        // Checked, not wrapping: a corrupted bound (or an id near `u64::MAX`)
        // would otherwise wrap the next bound to 0, and 0 is exactly the
        // "no id" value this reservation exists to keep out of circulation.
        // There is no safe value to clamp to, so fail loudly instead.
        let new = (v / self.block)
            .checked_add(1)
            .and_then(|blocks| blocks.checked_mul(self.block))
            .ok_or_else(|| {
                StorageError::Codec(format!(
                    "reservation bound {} cannot cover id {v} in blocks of {}: \
                     the next bound would overflow u64",
                    String::from_utf8_lossy(self.key),
                    self.block,
                ))
            })?;
        backend.put(self.key, &new.to_be_bytes())?;
        self.bound.store(new, Ordering::Release);
        Ok(())
    }
}

impl<B: KvBackend> Journal<B> {
    /// Open a journal on `backend`, continuing its sequence numbering.
    pub fn open(backend: B) -> Result<Self, StorageError> {
        let next = match read_bound(&backend, K_RESERVED)? {
            Some(bound) => bound,
            // No reservation: a journal from before reservations, or one that
            // lost the key. Resume above both the old head and the highest
            // event actually present — resuming below an existing event would
            // overwrite history, which is the one thing this layer must not do.
            None => {
                let head = read_u64(backend.get(K_HEAD)?).map_or(1, |h| h + 1);
                let last = backend.scan_prefix(&[K_EVENT])?.last().map_or(1, |(k, _)| {
                    u64::from_be_bytes(k[1..9].try_into().unwrap()) + 1
                });
                head.max(last)
            }
        };
        Ok(Self {
            backend,
            next_seq: AtomicU64::new(next),
            // Nothing at or above `next` is reserved yet; the first append
            // writes a bound before it writes an event.
            reserved: Reservation::new(K_RESERVED, SEQ_BLOCK, next),
            sink: None,
        })
    }

    /// Make sure `seq` lies below the persisted reservation bound. The bound
    /// is durable before the event that needs it is written.
    fn reserve(&self, seq: u64) -> Result<(), StorageError> {
        self.reserved.ensure(&self.backend, seq)
    }

    /// Mirror every appended event into `sink` as well.
    ///
    /// The mirror is derived, never authoritative: a journal with no sink
    /// behaves identically, and one whose sink is failing loses nothing that
    /// matters. See the [`sink`] module for why that is the design.
    pub fn with_sink(mut self, sink: BatchingSink) -> Self {
        self.sink = Some(sink);
        self
    }

    /// What the mirror has managed to do, if there is one.
    pub fn sink_stats(&self) -> Option<&SinkStats> {
        self.sink.as_ref().map(|s| s.stats())
    }

    /// Borrow the backend (for flushing alongside the world's own store).
    pub fn backend(&self) -> &B {
        &self.backend
    }

    /// The sequence number the next append will receive.
    pub fn head(&self) -> u64 {
        self.next_seq.load(Ordering::SeqCst)
    }

    /// Append `body` by `actor`, stamped now. Returns the assigned sequence
    /// number.
    pub fn append(&self, actor: ActorId, body: EventBody) -> Result<u64, StorageError> {
        self.append_at(actor, body, now_ms())
    }

    /// [`Journal::append`] with an explicit timestamp, so tests do not depend
    /// on the clock.
    pub fn append_at(
        &self,
        actor: ActorId,
        body: EventBody,
        at_ms: u64,
    ) -> Result<u64, StorageError> {
        self.append_full(actor, body, None, at_ms)
    }

    /// Append one bulk-edit **revision**: many block changes under a single
    /// sequence number, actor and timestamp.
    ///
    /// Returns the revision's sequence number — which is also its undo id,
    /// because the event carries both sides of every change — or `None` when
    /// `changes` is empty, so nothing was written and there is no id to hand
    /// back mistaken for the previous event's. The changes are stored sorted
    /// by column, which lets a column replay binary-search its own slice
    /// rather than scan a whole million-block revision per column.
    pub fn append_block_group(
        &self,
        actor: ActorId,
        mut changes: Vec<BlockChange>,
    ) -> Result<Option<u64>, StorageError> {
        if changes.is_empty() {
            return Ok(None);
        }
        changes.sort_by_key(|c| (c.x >> 4, c.z >> 4, c.y, c.x, c.z));
        self.append(actor, EventBody::BlockGroup { changes })
            .map(Some)
    }

    /// Append an event that happened because of event `cause` — a drop out of
    /// the block break that produced it.
    pub fn append_caused(
        &self,
        actor: ActorId,
        body: EventBody,
        cause: Option<u64>,
    ) -> Result<u64, StorageError> {
        self.append_full(actor, body, cause, now_ms())
    }

    fn append_full(
        &self,
        actor: ActorId,
        body: EventBody,
        cause: Option<u64>,
        at_ms: u64,
    ) -> Result<u64, StorageError> {
        let seq = self.next_seq.fetch_add(1, Ordering::SeqCst);
        self.reserve(seq)?;
        // Enforce the column-sorted invariant for a bulk revision here, at the
        // one place every event passes through — not only in
        // `append_block_group`. A caller may append a `BlockGroup` directly
        // (`append`/`append_at`/`append_caused`), and the replay in
        // `World::ensure_column` binary-searches the stored list on the
        // assumption it is sorted; an unsorted group would silently lose
        // columns. Sorting is idempotent, so the builder's own sort is left
        // where it is.
        let body = match body {
            EventBody::BlockGroup { mut changes } => {
                changes.sort_by_key(|c| (c.x >> 4, c.z >> 4, c.y, c.x, c.z));
                EventBody::BlockGroup { changes }
            }
            other => other,
        };
        let e = Event {
            seq,
            at_ms,
            actor,
            cause,
            body,
        };
        // The payload goes down before either index, so a crash between writes
        // can leave an event nothing points at (harmless: it is skipped) but
        // never an index entry pointing at nothing (which would read as
        // corruption).
        self.backend.put(&event_key(seq), &e.encode())?;
        // One column entry per block position the event touches. A block
        // change touches its own block; an item event touches both ends of its
        // movement, so a container's column sees a transfer that leaves it for
        // another chunk, not only one that lands on it.
        for (x, _, z) in e.body.indexed_positions() {
            self.backend.put(&column_key(x >> 4, z >> 4, seq), &[])?;
        }
        self.backend.put(&actor_key(actor, seq), &[])?;
        // One entry per item instance the event names, so an item's whole
        // history is a prefix read of its own entries. A block event names
        // none and writes none.
        for uid in e.body.item_uids() {
            self.backend.put(&item_key(uid, seq), &[])?;
        }
        // After the durable write, never before: the mirror must not be able
        // to show an event the journal does not have.
        if let Some(sink) = &self.sink {
            sink.submit(&e);
        }
        Ok(seq)
    }

    /// Read one event by sequence number.
    pub fn get(&self, seq: u64) -> Result<Option<Event>, StorageError> {
        match self.backend.get(&event_key(seq))? {
            Some(blob) => Event::decode(&blob)
                .map(Some)
                .map_err(|e| StorageError::Codec(e.to_string())),
            None => Ok(None),
        }
    }

    /// Every event affecting column `(cx, cz)`, oldest first.
    ///
    /// This is the read the world does when it materializes a column: generate
    /// the baseline, then replay these over it.
    pub fn column_events(&self, cx: i32, cz: i32) -> Result<Vec<Event>, StorageError> {
        self.column_events_from(cx, cz, 0)
    }

    /// The events affecting column `(cx, cz)` numbered `from` or later,
    /// oldest first — the tail after a checkpoint. Earlier events are skipped
    /// on their index key alone, without being read.
    pub fn column_events_from(
        &self,
        cx: i32,
        cz: i32,
        from: u64,
    ) -> Result<Vec<Event>, StorageError> {
        let mut out = Vec::new();
        for (k, _) in self.backend.scan_prefix(&column_prefix(cx, cz))? {
            let seq = u64::from_be_bytes(k[9..17].try_into().unwrap());
            if seq < from {
                continue;
            }
            if let Some(e) = self.get(seq)? {
                out.push(e);
            }
        }
        Ok(out)
    }

    /// The most recent event touching the block at `(x, y, z)`, if anyone has
    /// ever touched it.
    ///
    /// "Touching" is broad: a block change at the position, but also an item
    /// event whose place is that block (a drop landing there, a container
    /// access at its coordinates). A caller that means strictly "was this
    /// block changed" wants [`Self::last_block_change_at`].
    pub fn last_change_at(&self, x: i32, y: i32, z: i32) -> Result<Option<Event>, StorageError> {
        self.first_column_hit(x, z, &|e| e.body.touches_position(x, y, z))
    }

    /// The most recent **block change** at `(x, y, z)`, if the block there was
    /// ever placed or broken.
    ///
    /// Item events that merely happen to sit at the coordinates — a dropped
    /// item, a chest opening — are ignored, so this is the "was the block
    /// itself edited" question the worldgen-original check needs: a player who
    /// mined a natural diamond and dropped items on the spot has not made the
    /// block original or non-original by the drop.
    pub fn last_block_change_at(
        &self,
        x: i32,
        y: i32,
        z: i32,
    ) -> Result<Option<Event>, StorageError> {
        self.first_column_hit(x, z, &|e| e.body.changes_block_at(x, y, z))
    }

    /// The newest event in `(x, z)`'s column for which `accept` holds, walking
    /// the column index backwards and stopping at the first hit.
    ///
    /// Lazy and reverse: it reads the index from the newest key down and only
    /// decodes an event when the key is a candidate, so the cost is the number
    /// of column entries after the match rather than a materialised scan.
    fn first_column_hit(
        &self,
        x: i32,
        z: i32,
        accept: &dyn Fn(&Event) -> bool,
    ) -> Result<Option<Event>, StorageError> {
        let mut found = None;
        self.backend
            .scan_prefix_each_rev(&column_prefix(x >> 4, z >> 4), &mut |k, _| {
                if k.len() < 17 {
                    return Ok(true);
                }
                let seq = u64::from_be_bytes(k[9..17].try_into().unwrap());
                if let Some(e) = self.get(seq)? {
                    if accept(&e) {
                        found = Some(e);
                        return Ok(false);
                    }
                }
                Ok(true)
            })?;
        Ok(found)
    }

    /// Every event by `actor`, oldest first.
    pub fn actor_events(&self, actor: ActorId) -> Result<Vec<Event>, StorageError> {
        let mut out = Vec::new();
        for (k, _) in self.backend.scan_prefix(&actor_prefix(actor))? {
            // The index key is the 17-byte actor prefix plus an 8-byte seq. A
            // shorter key under the same prefix — a saved-player blob written
            // before the prefixes were pulled apart — is not an index entry;
            // skip it rather than panic slicing it.
            if k.len() < 25 {
                continue;
            }
            let seq = u64::from_be_bytes(k[17..25].try_into().unwrap());
            if let Some(e) = self.get(seq)? {
                out.push(e);
            }
        }
        Ok(out)
    }

    /// Stream every event, oldest first, decoding one at a time.
    ///
    /// The event is borrowed for the call only; clone it to keep it. Blobs
    /// that will not decode are skipped, as in [`Self::all_events`]: a
    /// corrupt tail must not hide the events before it.
    pub fn for_each_event<F>(&self, mut f: F) -> Result<(), StorageError>
    where
        F: FnMut(&Event) -> Result<(), StorageError>,
    {
        self.backend.scan_prefix_each(&[K_EVENT], &mut |_k, v| {
            if let Ok(e) = Event::decode(v) {
                f(&e)?;
            }
            Ok(true)
        })
    }

    /// Stream `actor`'s events, oldest first, decoding one at a time.
    pub fn for_each_actor_event<F>(&self, actor: ActorId, mut f: F) -> Result<(), StorageError>
    where
        F: FnMut(&Event) -> Result<(), StorageError>,
    {
        self.backend
            .scan_prefix_each(&actor_prefix(actor), &mut |k, _| {
                if k.len() >= 25 {
                    let seq = u64::from_be_bytes(k[17..25].try_into().unwrap());
                    if let Some(e) = self.get(seq)? {
                        f(&e)?;
                    }
                }
                Ok(true)
            })
    }

    /// The `limit` newest events overall, oldest first.
    ///
    /// Walks sequence numbers down from the head — a bounded number of point
    /// reads — rather than scanning the event index into a `Vec`. The gap the
    /// reservation can leave at the head is at most [`SEQ_BLOCK`].
    pub fn recent_events(&self, limit: usize) -> Result<Vec<Event>, StorageError> {
        let mut out = Vec::with_capacity(limit);
        let mut seq = self.head();
        while out.len() < limit && seq > 0 {
            seq -= 1;
            if let Some(e) = self.get(seq)? {
                out.push(e);
            }
        }
        out.reverse();
        Ok(out)
    }

    /// The `limit` newest events by `actor`, oldest first.
    ///
    /// Uses the actor index, whose entries carry no payload, so only the
    /// chosen events are read.
    pub fn actor_events_recent(
        &self,
        actor: ActorId,
        limit: usize,
    ) -> Result<Vec<Event>, StorageError> {
        let seqs = self.recent_index_seqs(&actor_prefix(actor), 17, limit)?;
        self.decode_seqs(&seqs)
    }

    /// The `limit` newest events affecting column `(cx, cz)`, oldest first.
    pub fn column_events_recent(
        &self,
        cx: i32,
        cz: i32,
        limit: usize,
    ) -> Result<Vec<Event>, StorageError> {
        let seqs = self.recent_index_seqs(&column_prefix(cx, cz), 9, limit)?;
        self.decode_seqs(&seqs)
    }

    /// Events numbered `since` or later, oldest first, at most `limit` — a
    /// bounded forward read for a caller following the journal with a cursor.
    pub fn events_since(&self, since: u64, limit: usize) -> Result<Vec<Event>, StorageError> {
        let mut out = Vec::with_capacity(limit);
        let head = self.head();
        let mut seq = since;
        while out.len() < limit && seq < head {
            if let Some(e) = self.get(seq)? {
                out.push(e);
            }
            seq += 1;
        }
        Ok(out)
    }

    /// The highest `limit` sequence numbers under `prefix`, oldest first.
    ///
    /// The index entries carry no payload, so they are scanned lazily and
    /// only a ring buffer of their sequence numbers is kept: a bounded query
    /// never holds the whole index, let alone the whole history.
    fn recent_index_seqs(
        &self,
        prefix: &[u8],
        seq_at: usize,
        limit: usize,
    ) -> Result<Vec<u64>, StorageError> {
        if limit == 0 {
            return Ok(Vec::new());
        }
        let mut ring: std::collections::VecDeque<u64> =
            std::collections::VecDeque::with_capacity(limit + 1);
        self.backend.scan_prefix_each(prefix, &mut |k, _| {
            if k.len() >= seq_at + 8 {
                let seq = u64::from_be_bytes(k[seq_at..seq_at + 8].try_into().unwrap());
                if ring.len() == limit {
                    ring.pop_front();
                }
                ring.push_back(seq);
            }
            Ok(true)
        })?;
        Ok(ring.into_iter().collect())
    }

    fn decode_seqs(&self, seqs: &[u64]) -> Result<Vec<Event>, StorageError> {
        let mut out = Vec::with_capacity(seqs.len());
        for &s in seqs {
            if let Some(e) = self.get(s)? {
                out.push(e);
            }
        }
        Ok(out)
    }

    /// The whole history, oldest first — for tests and tooling that genuinely
    /// needs it in memory at once. The server's commands use the bounded
    /// queries ([`Self::recent_events`], [`Self::actor_events_recent`],
    /// [`Self::column_events_recent`]) and [`Self::for_each_event`] instead.
    pub fn all_events(&self) -> Result<Vec<Event>, StorageError> {
        let mut out = Vec::new();
        for (_, v) in self.backend.scan_prefix(&[K_EVENT])? {
            if let Ok(e) = Event::decode(&v) {
                out.push(e);
            }
        }
        Ok(out)
    }

    /// The block changes that undo everything `filter` selects, **newest
    /// first**.
    ///
    /// Applying them in the returned order is required, not merely tidy: two
    /// edits to the same block only unwind correctly from the top of the
    /// stack down.
    ///
    /// Scans the actor index when the filter names one, so a per-player
    /// rollback costs that player's history rather than the world's.
    pub fn plan_rollback(&self, filter: &Filter) -> Result<Vec<Restore>, StorageError> {
        self.plan_rollback_where(filter, &|_| true)
    }

    /// [`Journal::plan_rollback`] with an extra predicate applied after the
    /// filter — for conditions no index can narrow, such as a block name.
    ///
    /// The journal is streamed oldest-first, so a rollback over the whole
    /// history does not materialise every event in memory: only the plan and
    /// one index entry per touched position are kept.
    pub fn plan_rollback_where(
        &self,
        filter: &Filter,
        accept: &dyn Fn(&Event) -> bool,
    ) -> Result<Vec<Restore>, StorageError> {
        // A position touched several times collapses to one restoration, and
        // the two halves come from opposite ends of the oldest-first walk:
        //
        // * `block` — what to put back — is the **oldest** selected `from`,
        //   the state before the first edit being undone. Taking a newer one
        //   would restore the block to a state it held midway through.
        // * `removed` — what the undo takes away, and therefore what the
        //   recovery stash is owed — is the **newest** selected `to`, the last
        //   thing the filter's subject actually put there.
        //
        // So the first sighting sets both and later sightings update `removed`.
        let mut order: std::collections::HashMap<(i32, i32, i32), (usize, u64)> =
            std::collections::HashMap::new();
        let mut plan: Vec<Restore> = Vec::new();
        // Fold one block change into the plan. A single `BlockSet` is one such
        // change; a `BlockGroup` (a bulk edit revision) is many, all sharing
        // the event's sequence and actor, so each is expanded here and a
        // rollback of the revision restores every block it touched.
        let record = |order: &mut std::collections::HashMap<(i32, i32, i32), (usize, u64)>,
                      plan: &mut Vec<Restore>,
                      x: i32,
                      y: i32,
                      z: i32,
                      from: BlockStateId,
                      to: BlockStateId,
                      seq: u64| {
            match order.get(&(x, y, z)) {
                Some(&(i, _)) => {
                    plan[i].removed = to;
                    order.insert((x, y, z), (i, seq));
                }
                None => {
                    order.insert((x, y, z), (plan.len(), seq));
                    plan.push(Restore {
                        x,
                        y,
                        z,
                        block: from,
                        removed: to,
                        undoing: seq,
                    });
                }
            }
        };
        let mut visit = |e: &Event| -> Result<(), StorageError> {
            if !filter.matches(e) || !accept(e) {
                return Ok(());
            }
            match &e.body {
                EventBody::BlockSet { x, y, z, from, to } => {
                    record(&mut order, &mut plan, *x, *y, *z, *from, *to, e.seq);
                }
                EventBody::BlockGroup { changes } => {
                    for c in changes {
                        record(&mut order, &mut plan, c.x, c.y, c.z, c.from, c.to, e.seq);
                    }
                }
                _ => {}
            }
            Ok(())
        };
        match filter.actor {
            Some(a) => self.for_each_actor_event(a, &mut visit)?,
            None => self.for_each_event(&mut visit)?,
        }
        drop(visit);
        // The former newest-first walk pushed a position on its newest
        // sighting; keep that order for callers that read the plan.
        plan.sort_by_key(|r| std::cmp::Reverse(order.get(&(r.x, r.y, r.z)).map_or(0, |&(_, s)| s)));
        Ok(plan)
    }
}

/// Milliseconds since the Unix epoch, or 0 if the clock is before it.
pub fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}
